   281  /**
   282   * hb_subset_glyf:
   283   * Subsets the glyph table according to a provided plan.
   284   *
   285   * Return value: subsetted glyf table.
   286   *
   287   * Since: 1.7.5
   288   **/
   289  bool
   290  hb_subset_glyf_and_loca (hb_subset_plan_t *plan,
   233    struct accelerator_t
   234    {
   235      inline void init (hb_face_t *face)
   236      {
   237        memset (this, 0, sizeof (accelerator_t));
   238
   239        hb_blob_t *head_blob = hb_sanitize_context_t().reference_table<head> (face);
   240        const head *head_table = head_blob->as<head> ();
   241        if (head_table->indexToLocFormat > 1 || head_table->glyphDataFormat != 0)
   242        {
   243          /* Unknown format.  Leave num_glyphs=0, that takes care of disabling us. */
   244          hb_blob_destroy (head_blob);
   245          return;
   246        }
   247        short_offset = 0 == head_table->indexToLocFormat;
   248        hb_blob_destroy (head_blob);
   249
   250        loca_blob = hb_sanitize_context_t().reference_table<loca> (face);
   251        loca_table = loca_blob->as<loca> ();
   252        glyf_blob = hb_sanitize_context_t().reference_table<glyf> (face);
   253        glyf_table = glyf_blob->as<glyf> ();
   254
   255        num_glyphs = MAX (1u, hb_blob_get_length (loca_blob) / (short_offset ? 2 : 4)) - 1;
   256        glyf_len = hb_blob_get_length (glyf_blob);
   257      }
   258
   259      inline void fini (void)
   260      {
   261        hb_blob_destroy (loca_blob);
   262        hb_blob_destroy (glyf_blob);
   263      }
